package __BUNDLE_ID__

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import __BUNDLE_ID__.data.ContractFixtures
import __BUNDLE_ID__.ui.TaskScreen

/// Phase 2 reference shell. The app renders the shared "populated" contract
/// fixture so every platform shows identical states while the Swift→JNI
/// bridge (swift-java, generated by `swiftport sync`) is wired in.
class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        val state = ContractFixtures.fromAssets(assets, "populated.json")
        setContent {
            TaskScreen(state = state)
        }
    }
}
